def summarize_array_copy(loop, scope, initial=None):
    if loop is None or loop.type != 'for_statement':
        return None
    init = _field(loop, 'initializer')
    condition = _field(loop, 'condition')
    update = _field(loop, 'increment')
    body = _field(loop, 'body')
    if init is None or condition is None or update is None or body is None:
        return None
    if body.type != 'statement_block':
        return None
    declarators = [child for child in init.named_children if child.type == 'variable_declarator']
    if len(declarators) != 1:
        return None
    variable = _field(declarators[0], 'name')
    start = _field(declarators[0], 'value')
    if variable is None or variable.type != 'identifier' or start is None:
        return None
    if text(start).strip() != '0':
        return None
    index_name = text(variable)
    if condition.type != 'binary_expression' or _tokens(condition) != ['<']:
        return None
    left, right = _field(condition, 'left'), _field(condition, 'right')
    if left is None or right is None or text(left) != index_name:
        return None
    if update.type != 'update_expression' or _tokens(update) != ['++']:
        return None
    argument = _field(update, 'argument')
    if argument is None or text(argument) != index_name:
        return None
    definitions, uncertain = definitions_before(scope, loop, initial)
    aliases = dict(initial or {})
    aliases.update(definitions)
    used = set()
    condition_source = _simple_source(_length_source(text(right), aliases, used), aliases, used)
    if condition_source is None:
        return None
    statements = [child for child in body.named_children if child.type != 'comment']
    if len(statements) != 1 or statements[0].type != 'expression_statement':
        return None
    expressions = statements[0].named_children
    if len(expressions) != 1 or expressions[0].type != 'assignment_expression':
        return None
    assignment = expressions[0]
    if _tokens(assignment) != ['=']:
        return None
    target, source = _field(assignment, 'left'), _field(assignment, 'right')
    if target is None or source is None:
        return None
    if target.type != 'subscript_expression' or source.type != 'subscript_expression':
        return None
    target_index, source_index = _field(target, 'index'), _field(source, 'index')
    if target_index is None or source_index is None:
        return None
    if text(target_index) != index_name or text(source_index) != index_name:
        return None
    target_member = _field(target, 'object')
    if target_member is None or target_member.type != 'member_expression':
        return None
    receiver, key_node = _field(target_member, 'object'), _field(target_member, 'property')
    if receiver is None or key_node is None or key_node.type != 'identifier':
        return None
    resolved = 'this' if receiver.type == 'this' else _expand(text(receiver), aliases, used)
    if resolved != 'this':
        return None
    source_object = _field(source, 'object')
    if source_object is None or not _simple_read(source_object):
        return None
    if _simple_source(text(source_object), aliases, used) != condition_source:
        return None
