```python
def summarize_array_copy(loop, scope, initial=None):
    if loop is None or loop.type != 'for_statement':
        return None
    initializer = _field(loop, 'initializer')
    condition = _field(loop, 'condition')
    update = _field(loop, 'increment')
    body = _field(loop, 'body')
    if initializer is None or condition is None or update is None or body is None:
        return None
    if body.type != 'statement_block':
        return None
    declarators = [child for child in initializer.named_children
                   if child.type == 'variable_declarator']
    if len(declarators) != 1:
        return None
    index, start = _field(declarators[0], 'name'), _field(declarators[0], 'value')
    if index is None or index.type != 'identifier' or start is None or text(start).strip() != '0':
        return None
    index_name = text(index)
    if condition.type != 'binary_expression' or _tokens(condition) != ['<']:
        return None
    if text(_field(condition, 'left')) != index_name:
        return None
    if update.type != 'update_expression' or _tokens(update) != ['++']:
        return None
    if text(_field(update, 'argument')) != index_name:
        return None
    definitions, uncertain = definitions_before(scope, loop, initial)
    aliases = dict(initial or {})
    aliases.update(definitions)
    used = set()
    bound = _length_base(text(_field(condition, 'right')), aliases, used)
    condition_source = _source_read(bound, aliases, used) if bound is not None else None
    if condition_source is None:
        return None
    statements = [child for child in body.named_children if child.type != 'comment']
    if len(statements) != 1 or statements[0].type != 'expression_statement':
        return None
    assignment = statements[0].named_children
    if len(assignment) != 1 or assignment[0].type != 'assignment_expression':
        return None
    assignment = assignment[0]
    if _tokens(assignment) != ['=']:
        return None
    target, source = _field(assignment, 'left'), _field(assignment, 'right')
    if target is None or source is None:
        return None
    if target.type != 'subscript_expression' or source.type != 'subscript_expression':
        return None
    if text(_field(target, 'index')) != index_name or text(_field(source, 'index')) != index_name:
        return None
    target_member = _field(target, 'object')
    if target_member is None or target_member.type != 'member_expression':
        return None
    receiver, key_node = _field(target_member, 'object'), _field(target_member, 'property')
    if key_node is None or key_node.type not in ('identifier', 'property_identifier'):
        return None
    if receiver.type == 'this':
        resolved = 'this'
    else:
        resolved = _expand(text(receiver) if receiver is not None else '', aliases, used)
    if resolved != 'this':
        return None
    if _source_read(text(_field(source, 'object')), aliases, used) != condition_source:
        return None
    key = text(key_node)
    target_text = text(target_member)
    initialized = next((name for name in (target_text, 'this.' + key)
                        if _empty_array(definitions.get(name))), None)
    if initialized is None:
        return None
    used.add(initialized)
    if used & uncertain:
        return None
    return {'key': key, 'expr': condition_source, 'target': target_text,
            'line': loop.start_point[0] + 1}
```

